def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(x for row in grid for x in row), key=lambda c: sum(row.count(c) for row in grid))
    row_cuts = [r for r in range(h) if len(set(grid[r])) == 1 and grid[r][0] != bg]
    col_cuts = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != bg]

    def spans(n, cuts):
        result, start = [], 0
        for c in cuts:
            if start < c:
                result.append((start, c))
            start = c + 1
        if start < n:
            result.append((start, n))
        return result

    rs, cs = spans(h, row_cuts), spans(w, col_cuts)
    panels = []
    for r0, r1 in rs:
        for c0, c1 in cs:
            panel = [row[c0:c1] for row in grid[r0:r1]]
            panels.append((r0, r1, c0, c1, panel))

    source = None
    for panel in panels:
        r0, r1, c0, c1, data = panel
        if any(v != bg for row in data for v in row):
            source = panel
            break
    if source is None:
        return grid

    sr0, sr1, sc0, sc1, data = source
    out = [row[:] for row in grid]
    for r0, r1, c0, c1, _ in panels:
        if r1 - r0 == sr1 - sr0 and c1 - c0 == sc1 - sc0:
            for i in range(r1 - r0):
                out[r0 + i][c0:c1] = data[i][:]
    return out
